parameters.functionCode:
// Format appointment details
const appointments = items.map(item => {
  const apt = item.json;
  const aptDate = new Date(apt.appointment_date);

  return {
    json: {
      ...apt,
      formattedDate: aptDate.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      }),
      formattedTime: aptDate.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit'
      })
    }
  };
});

return appointments;

